function display(v,field,resource) { if(resource==='assets'&&field==='status')return ({ACTIVE:'فعال',DISPOSED:'اسقاط‌شده'})[v]||v;if(resource==='assets'&&field==='purchase_date'&&v)return formatPersianDate(String(v).slice(0,10)+'T12:00:00');if(resource==='products'&&field==='tax_type')return ({OFFICIAL:'رسمی / مشمول مالیات',UNOFFICIAL:'غیررسمی / غیرمشمول مالیات'})[v]||'تعیین نشده';if(field==='status'&&v==='PENDING_APPROVAL')return 'در انتظار تأیید';if(field==='status'&&v==='APPROVED')return 'تأییدشده';if(v===null||v===undefined||v==='')return '—';if(field==='period'&&/^\d{4}-\d{2}$/.test(String(v)))return formatPersianMonth(`${String(v)}-25T12:00:00`);if((field==='date'||field==='sourceDate'||field==='openingDate'||/(?:_date|_at)$/.test(field)||/[Dd]ate$/.test(field))&&v)return formatPersianDate(v,/_at$/.test(field));if(['is_active','isactive','is_postable'].includes(field)&&(v===true||v===false||v===0||v===1||v==='0'||v==='1'))return v===true||v===1||v==='1'?(field==='is_postable'?'بله':'فعال'):(field==='is_postable'?'خیر':'غیرفعال');if(['CASH','BANK','PETTY_CASH'].includes(v))return ({CASH:'صندوق',BANK:'بانک',PETTY_CASH:'تنخواه'})[v];if(['ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE','MEMORANDUM'].includes(v))return ({ASSET:'دارایی',LIABILITY:'بدهی',EQUITY:'حقوق صاحبان سهام',REVENUE:'درآمد',EXPENSE:'هزینه',MEMORANDUM:'انتظامی و آماری'})[v];if((resource==='products'&&['sale_price','last_purchase_price','average_purchase_price'].includes(field))||(resource==='treasury'&&['balance','limit_amount'].includes(field))||(resource==='assets'&&field==='purchase_cost')||(resource==='payables'&&['amount','settledAmount','balanceDue'].includes(field))||(resource==='journal-accounts'&&field==='balance')||(['payables-balances','receivables-balances'].includes(resource)&&['balanceDue','creditBalance'].includes(field)))return `${new Intl.NumberFormat('fa-IR').format(BigInt(v))} ریال`;if(resource==='products'&&field==='weight_kg')return `${new Intl.NumberFormat('fa-IR',{maximumFractionDigits:3}).format(Number(v))} کیلوگرم`;if(resource==='inventory'&&field==='product'&&typeof v==='object')return `${v.name||v.code||'محصول'} (${v.unit||'واحد'})`;if(typeof v==='object')return v.name||v.title||v.username||v.code||JSON.stringify(v);if(typeof v==='number')return new Intl.NumberFormat('fa-IR').format(v);if(typeof v==='boolean'||v===0||v===1)return v===true||v===1?'فعال':'غیرفعال';return String(v) }
const permissionActionLabels={read:'مشاهده',create:'ایجاد',update:'ویرایش',delete:'حذف',approve:'تأیید',close:'بستن',activate:'فعال‌سازی',archive:'بایگانی',release:'آزادسازی',complete:'تکمیل',cancel:'لغو',start:'شروع',hold:'توقف موقت',resume:'ازسرگیری',block:'مسدودکردن',reject:'رد',pickup:'تحویل به پیک',transit:'ثبت در مسیر',deliver:'ثبت تحویل',exception:'ثبت مشکل'}
function permissionName(permission){const name=String(permission?.name||'');const action=String(permission?.code||'').split('.').pop();const label=permissionActionLabels[action];if(!label||!new RegExp(`\\s-\\s${action}$`,'i').test(name))return name;const subject=name.replace(new RegExp(`\\s-\\s${action}$`,'i'),'').trim();if(action==='pickup')return `${label} ${subject}`;if(action==='transit')return `${label} ${subject}`;if(action==='deliver')return `${label} ${subject}`;if(action==='exception')return `${label} برای ${subject}`;return `${label} ${subject}`}
function pick(obj,key){ return key.split('.').reduce((v,k)=>v?.[k],obj) }
